def is_power_of_5(N):
    if N <= 0:
        return False
    if N == 1:
        return True
    while N % 5 == 0:
        N //= 5
    return N == 1

results = {}
for n in range(3, 11):
    value = (2**n) - 3
    is_pow5 = is_power_of_5(value)
    results[n] = (value, is_pow5)

print("n | 2^n - 3 | Is Power of 5?")
print("-" * 30)
for n, (value, is_pow5) in results.items():
    print(f"{n} | {value} | {is_pow5}")

# Detailed output for logging
print("\nDetailed results:")
